   $('[data-d="mention"]').onclick=()=>{if(pending)return;const input=$('[data-d="text"]');if(mentionOpen){mentionOpen=false;mentionPicker();input.focus({preventScroll:true});return;}syncText();if(!mentionToken()){const from=input.selectionStart??input.value.length,to=input.selectionEnd??from;refs=DiscussionText.replace(input.value,refs,from,to,'@');mentions=DiscussionText.replace(input.value,mentions,from,to,'@');input.value=lastText=input.value.slice(0,from)+'@'+input.value.slice(to);input.setSelectionRange?.(from+1,from+1);}resize();updateMention();input.focus({preventScroll:true});};
